class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        int cur = 0, maxSum = nums[0];
        for (int n : nums) { cur = max(n, cur + n); maxSum = max(maxSum, cur); }
        return maxSum;
    }
};

